#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

// ------------------------------------------------------------
// For chosen row-prefix lengths k_i and column-prefix lengths l_j,
// cell (i,j) becomes:
//   a[i][j] = [j <= k_i] + [i <= l_j]
//
// Let R_i = k_i, C_j = l_j.
// The produced 0/1/2-grid is uniquely determined by the pair of
// monotone boundary descriptions, but many pairs can yield same grid.
//
// Key characterization:
// For each row i, define x_i = number of columns with l_j >= i.
// Then row i is:
//   2 on columns j <= min(R_i, x_i)
//   1 on columns between min..max(R_i, x_i)
//   0 afterwards
// Hence each row is some number of 2's, then 1's, then 0's.
//
// Similarly columns have form 2's,1's,0's.
//
// A grid is realizable iff:
// - cells >=1 form a Ferrers diagram (row-wise nonincreasing row sums),
// - cells ==2 form a Ferrers diagram contained in it.
// Equivalently, choose two partitions:
//   b_1 >= ... >= b_N  (cells >=1 in each row)
//   a_1 >= ... >= a_N  (cells ==2 in each row)
//   with 0 <= a_i <= b_i <= M
// and additionally the skew shape b/a contains no 2x2 pattern forcing
// contradiction? In fact every nested Ferrers pair is realizable here.
// Counting such pairs equals product formula below.
//
// Another direct counting view:
// Scan rows top to bottom. Let
//   x_i = #columns with l_j >= i
// Then x_1 >= x_2 >= ... >= x_N, 0<=x_i<=M.
// For fixed x sequence, each row i chooses R_i in [0..M], producing
// pair (a_i,b_i) = (min(R_i,x_i), max(R_i,x_i)).
// Thus for fixed x_i=t, row i can choose any pair (a_i,b_i) with
// 0<=a_i<=t<=b_i<=M, and if t is strictly between a_i,b_i there are
// two possible R_i giving same pair? No, pair determines row pattern,
// and any such pair with t between endpoints is realizable.
// Global realizability requires a_i,b_i both nonincreasing.
// So x_i acts as an intermediate partition between a and b:
//   a_i <= x_i <= b_i, with a,b nonincreasing.
//
// Therefore number of grids equals number of pairs of partitions
// a<=b with an intermediate partition x.
// This is exactly the number of plane partitions in an N x M x 2 box.
// By MacMahon's formula:
//   PP(N,M,2) = prod_{i=1}^N prod_{j=1}^M prod_{k=1}^2
//                 (i+j+k-1)/(i+j+k-2)
// Telescopes in k:
//   = prod_{i=1}^N prod_{j=1}^M (i+j+1-1?)
// For k=1,2:
//   (i+j)/(i+j-1) * (i+j+1)/(i+j)
//   = (i+j+1)/(i+j-1)
// where i,j are 1-based.
// So answer:
//   prod_{i=1}^N prod_{j=1}^M (i+j)/(i+j-2)? let's verify carefully.
//
// MacMahon uses indices starting at 1:
// factor = (i+j+k-1)/(i+j+k-2)
// k=1 => (i+j)/(i+j-1)
// k=2 => (i+j+1)/(i+j)
// product => (i+j+1)/(i+j-1)
//
// Check N=M=1: possible grids are 0, row-only, col-only, both => values
// [0],[1],[1],[2] => 3 distinct grids {0,1,2}. Formula gives
// (1+1+1)/(1+1-1)=3/1=3 correct.
//
// So answer = prod_{i=1}^N prod_{j=1}^M (i+j+1)/(i+j-1).
// We compute modulo MOD using inverses.
// ------------------------------------------------------------

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, M;
    cin >> N >> M;

    long long limit = N + M + 2;
    vector<long long> inv(limit + 1);
    for (long long i = 1; i <= limit; i++) inv[i] = modpow(i, MOD - 2);

    long long ans = 1;
    for (long long i = 1; i <= N; i++) {
        for (long long j = 1; j <= M; j++) {
            ans = ans * (i + j + 1) % MOD;
            ans = ans * inv[i + j - 1] % MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

