def modinv(a):
    return pow(a, MOD - 2, MOD)

def comb(n, k):
    if k < 0 or k > n:
        return 0
    num = den = 1
    for i in range(k):
        num = num * (n - i) % MOD
        den = den * (i + 1) % MOD
    return num * modinv(den) % MOD

