#include <stdio.h>
#include <stdlib.h>

#define MOD 998244353LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, M;
    if (scanf("%lld %lld", &N, &M) != 2) return 0;

    /* 
       Let A(i,j)=1 iff j<=k_i  (row-prefix ones)
           B(i,j)=1 iff i<=l_j  (column-prefix ones)
       Final grid is C=A+B, values in {0,1,2}.

       A grid C determines, for each cell, whether:
         - C=0: both A,B are 0
         - C=2: both A,B are 1
         - C=1: exactly one of A,B is 1

       The number of distinct possible C is:
         sum_{t=0}^{min(N,M)} (t!)^2 * S(N+1,t+1) * S(M+1,t+1)
       where S(.,.) are Stirling numbers of the second kind.

       This can be transformed by inclusion-exclusion into:
         sum_{i=1}^{N+1} sum_{j=1}^{M+1} (-1)^{N+M-i-j} * C(N,i-1) * C(M,j-1) * (min(i,j))
       but that is too slow directly.

       A standard identity gives:
         answer = sum_{t=0}^{min(N,M)} f(N,t) * f(M,t)
       where f(X,t) = t! * S(X+1,t+1).

       And
         f(X,t) = sum_{k=0}^{t+1} (-1)^{t+1-k} C(t+1,k) k^X
       (surjection count onto t+1 labels with one distinguished last block removed equivalently).

       However X can be huge, but min(N,M) in the intended constraints is small enough for O(min^2).
       Since constraints are not shown here, we implement the DP for Stirling numbers up to min(N,M),
       which is the standard accepted approach when N,M are up to 3000 or similar.

       We compute for smaller dimension K=min(N,M):
         dp[a][b] = S(a,b) for a up to larger+1 would be too large if larger huge.
       Instead use explicit formula:
         f(X,t) = sum_{k=0}^{t+1} (-1)^{t+1-k} C(t+1,k) k^X
       for t<=K.
       Precompute binomials up to K+1 and powers k^N, k^M.
    */

    long long K = (N < M ? N : M);

    long long *fact = (long long*)malloc((K + 2) * sizeof(long long));
    long long *invfact = (long long*)malloc((K + 2) * sizeof(long long));
    fact[0] = 1;
    for (long long i = 1; i <= K + 1; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[K + 1] = mod_pow(fact[K + 1], MOD - 2);
    for (long long i = K + 1; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long *powN = (long long*)malloc((K + 2) * sizeof(long long));
    long long *powM = (long long*)malloc((K + 2) * sizeof(long long));
    for (long long k = 0; k <= K + 1; k++) {
        if (k == 0) {
            powN[k] = (N == 0 ? 1 : 0);
            powM[k] = (M == 0 ? 1 : 0);
        } else {
            powN[k] = mod_pow(k, N);
            powM[k] = mod_pow(k, M);
        }
    }

    long long *fN = (long long*)malloc((K + 1) * sizeof(long long));
    long long *fM = (long long*)malloc((K + 1) * sizeof(long long));

    for (long long t = 0; t <= K; t++) {
        long long sN = 0, sM = 0;
        long long tp1 = t + 1;
        for (long long k = 0; k <= tp1; k++) {
            long long comb = fact[tp1] * invfact[k] % MOD * invfact[tp1 - k] % MOD;
            long long sign = ((tp1 - k) & 1) ? (MOD - 1) : 1;
            sN = (sN + sign * comb % MOD * powN[k]) % MOD;
            sM = (sM + sign * comb % MOD * powM[k]) % MOD;
        }
        fN[t] = sN;
        fM[t] = sM;
    }

    long long ans = 0;
    for (long long t = 0; t <= K; t++) {
        ans = (ans + fN[t] * fM[t]) % MOD;
    }

    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    free(powN);
    free(powM);
    free(fN);
    free(fM);
    return 0;
}
